WITH category_node AS (
    SELECT id FROM sys_category WHERE app_code = 'youanshang' AND type = 'knowledge_point' AND code = 'kp_xingce_judgement_definition_multi_inclusive'
)
INSERT INTO sys_content (app_code, title, slug, content_json, content_html, summary, category_id, tags, is_pinned, is_public, is_published, publish_time, view_count, sort_order, extra, created_by, created_time)
SELECT 'gongkao', '包含定义', 'kp-xingce-judgement-definition-multi-inclusive', CAST($${"type": "doc", "content": [{"type": "heading", "attrs": {"level": 1}, "content": [{"type": "text", "text": "多定义：包含关系"}]}, {"type": "highlightBlock", "attrs": {"backgroundColor": "#fffbeb", "borderColor": "#f59e0b", "icon": "💡"}, "content": [{"type": "paragraph", "content": [{"type": "text", "text": "核心战术：", "marks": [{"type": "bold"}]}, {"type": "text", "text": "大概念套小概念。"}]}]}, {"type": "heading", "attrs": {"level": 2}, "content": [{"type": "text", "text": "一、破题法"}]}, {"type": "paragraph", "content": [{"type": "text", "text": "题干给了“无形资产”和“商誉”两个定义。商誉显然是无形资产的一种。看清题目到底问的是哪个定义的例子，不要把包含的小类当成并列关系处理。"}]}]}$$ AS jsonb), NULL, '包含定义的核心考点与解题技巧。', category_node.id, CAST('["判断推理", "包含定义"]' AS jsonb), FALSE, TRUE, TRUE, NOW(), 0, 0, CAST('{"content_type": "knowledge_point", "category_code": "kp_xingce_judgement_definition_multi_inclusive", "source": "fba_content_engine"}' AS jsonb), 1, NOW()
FROM category_node ON CONFLICT (slug) DO UPDATE SET title = EXCLUDED.title, content_json = EXCLUDED.content_json, summary = EXCLUDED.summary, category_id = EXCLUDED.category_id, tags = EXCLUDED.tags, updated_time = NOW();
